VALUES ('Azerbaijan — Dashkasan Region (No Commercial Coal; Iron Ore Territory)', 'No coal operator. Iron ore: Dashkasan Iron Ore LLC (DDF) — subsidiary of AzerGold CJSC', 'None for coal', NULL, NULL, 'Azerbaijan', 'Ganja-Dashkasan Economic Region', 'Dashkasan District, Lesser Caucasus Mountains, ~40°35''N 46°05''E approximate', 40.59, 46.08, 'Baku (Caspian port, ~300 km east via road)', 'Ganja railway station (~100 km east) — connected to Baku main line', NULL, NULL, NULL, '[{"year": 1945, "event": "Dashkasan iron ore mine (NOT coal) established under Soviet era"}, {"year": 1991, "event": "Soviet collapse — iron ore operations wound down"}, {"year": 2020, "event": "Dashkasan Iron Ore LLC (DDF) established as AzerGold subsidiary"}, {"year": 2024, "event": "Feasibility study completed by Micon International — 21-year iron ore mining plan; HBI production planned 2 Mt/yr by 2029"}, {"year": 2025, "event": "Meetings between AzerGold/DDF and Sinosure/Sinosteel (China) on $1.2bn HBI plant investment"}]'::jsonb, '[{"year": null, "event": "Dashkasan iron ore — one of South Caucasus largest iron ore deposits (309 Mt confirmed resource)"}, {"year": null, "event": "Azerbaijan has NO coal-fired power stations; electricity from gas turbines (90%) and hydropower (10%)"}, {"year": null, "event": "Azerbaijan is major oil and gas producer (SOCAR); coal irrelevant to energy economy"}]'::jsonb, '[{"year": null, "event": "Dashkasan was company town under Soviet era — 1991 collapse caused mass unemployment"}, {"year": null, "event": "Dashkasan region was near Nagorno-Karabakh conflict zone — post-2020 Karabakh reintegration stabilised region"}]'::jsonb, NULL, 'N/A — no coal', 'Skarn-magnetite iron ore district; Jurassic volcanic-sedimentary; metamorphic/igneous — incompatible with coal formation', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, '[]'::jsonb)
