INSERT INTO public.coal_mines (mine_name, operator, license_number, contact_email, contact_phone, country, region, address, latitude, longitude, nearest_port, nearest_railway, founded_year, years_in_operation, original_owner, ownership_changes, major_milestones, notable_incidents, estimated_mine_life_remaining_years, coal_type, grade, calorific_value_kcal_kg, moisture_percent, ash_percent, sulfur_percent, size_mm, annual_capacity_tonnes, available_stock_tonnes, mining_method, price_per_tonne_usd, price_basis, minimum_order_tonnes, payment_terms, contract_types, loading_port, transport_modes, lead_time_days, export_license, certifications)
VALUES ('Karkar Coal Mine — Baghlan Province (Afghan Coal LLC / NCE)', 'Afghan Coal LLC (AIC subsidiary) under privatisation agreement; Taliban MOMP licensing post-2021', 'Privatisation agreement 2007 (AIC); Taliban MOMP contracts post-2021', NULL, NULL, 'Afghanistan', 'Baghlan Province', 'Karkar area, ~12 km northeast of Pol-e Khomri, Baghlan Province', 35.50, 68.80, 'Hairatan border crossing (Uzbekistan, ~200 km north via road)', 'Hand-worked narrow-gauge mine railways (internal only; 120–320 m inclines); no national railway', 1939, 85, 'Ministry of Mines coal branch', '[{"year": 1939, "event": "Production commenced — initial workforce used donkeys to carry coal"}, {"year": 1957, "event": "Czechoslovak technical assistance began; Warsaw Pact equipment supplied"}, {"year": 2007, "event": "Four mines (Karkar, Dudkash, Ahandara, Khurdara) transferred to AIC subsidiary Afghan Coal LLC"}, {"year": 2021, "event": "Taliban 2.0 takeover — coal production sharply increased; coal taxes reportedly Taliban single largest revenue source"}, {"year": 2023, "event": "Taliban Ministry of Mines issued 167 extraction contracts Sept 2023–Sept 2024"}]'::jsonb, '[{"year": null, "event": "Afghanistan most historically significant coal operation; part of country only commercially producing coal complex"}, {"year": null, "event": "Peak production 1970s: Karkar alone employed 1,600 people, 600–700 tonnes/day"}, {"year": null, "event": "215–430 Mt total Afghan Jurassic coal resources; 51–89 Mt extracted since 1940"}, {"year": null, "event": "Coal taxes likely Taliban government single largest operating income source"}]'::jsonb, '[{"year": null, "event": "Frequent tunnel collapse, gas and coal dust explosions, uncontrolled mine fires"}, {"year": null, "event": "Child labour documented (US Dept of Labor)"}, {"year": null, "event": "ScienceDirect 2024: haphazard artisanal extraction left significant coal volumes permanently unrecoverable"}, {"year": null, "event": "Taliban taxing mines increased production but reduced safety oversight to near-zero"}]'::jsonb, NULL, 'Sub-bituminous to bituminous', 'Jurassic coal-bearing sedimentary basins; Karkar-Dudkash coalfield; Baghlan-Tukhar basin', NULL, NULL, NULL, NULL, NULL, 750000, NULL, 'Artisanal room-and-pillar; hand tools; wagons winched up inclines; no systematic plan', NULL, NULL, NULL, NULL, NULL, 'Hairatan (road)', '["Truck road transport (Kabul-Mazar-i-Sharif Highway)"]'::jsonb, NULL, false, '[]'::jsonb)
