VALUES ('Ishpushta Coal Mine — Baghlan Province', 'North Coal Enterprise (NCE) historically; Taliban MOMP post-2021 licensing; artisanal/small-scale under Taliban concession', 'Taliban MOMP contract — exact details undisclosed post-2021', NULL, NULL, 'Afghanistan', 'Baghlan Province', 'Ishpushta area, Nahrin District, Baghlan Province', 35.83, 69.08, 'Hairatan border (Uzbekistan) — ~250 km north via road', 'No railway; road access only', NULL, NULL, 'NCE (Directorate of Northern Coal Enterprise)', '[{"year": 1970, "event": "NCE (Directorate of Northern Coal Enterprise) takes over operations"}, {"year": 2001, "event": "Post-Taliban 1.0: government investment through NCE to reinstate capacity"}, {"year": 2021, "event": "Taliban 2.0: MOMP assumes licensing; coal taxes levied on all operating mines"}, {"year": 2023, "event": "Taliban announces $6.5 billion in new mining deals; Baghlan coal sector included"}]'::jsonb, '[{"year": null, "event": "Operated alongside Karkar under NCE umbrella historically"}, {"year": null, "event": "Part of broader Baghlan coalfield complex"}, {"year": null, "event": "Taliban 2.0: coal sector expansion — multiple new extraction contracts 2021–2024"}]'::jsonb, '[{"year": null, "event": "Child labour documented across all Afghan coal mines including Baghlan (USDOL)"}, {"year": null, "event": "Same safety conditions as Karkar: no gas monitoring; no systematic ventilation; artisanal methods"}]'::jsonb, NULL, 'Sub-bituminous to bituminous', 'Jurassic coal-bearing sedimentary basin; Ishpushta-Nahrin coalfield; same geological setting as Karkar', NULL, NULL, NULL, NULL, NULL, 0, NULL, 'Artisanal room-and-pillar; hand tools; no mechanisation', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, '[]'::jsonb)
