VALUES ('Dara-i-Suf Coal Mines — Samangan Province', 'Taliban MOMP licensing; Afghan artisanal mining companies under MOMP contracts; Dahna Toor Coal Mine operating', 'Taliban MOMP extraction contracts — details not publicly disclosed', NULL, NULL, 'Afghanistan', 'Samangan Province', 'Dara-e-Suf valley, Samangan Province; ~80 km south of Mazar-i-Sharif', 35.73, 67.83, 'Hairatan border (Uzbekistan) — ~280 km north', 'None in Samangan Province; nearest road to Mazar-i-Sharif (~80 km)', 1966, 58, 'Afghan government / Soviet-assisted exploration', '[{"year": 1966, "event": "Mining opened under Afghan government / Soviet-assisted exploration"}, {"year": 1979, "event": "Soviet intervention — operations severely disrupted"}, {"year": 1989, "event": "Soviet withdrawal; coalfield fell under mujahideen control"}, {"year": 1996, "event": "Taliban 1.0 control; artisanal operations continued"}, {"year": 2021, "event": "Taliban 2.0 — MOMP licensing; increased coal extraction as Taliban revenue source"}]'::jsonb, '[{"year": null, "event": "One of Afghanistan three traditional coal mining centres"}, {"year": null, "event": "Dahna Toor Coal Mine specifically operating (GEM-listed)"}, {"year": null, "event": "Post-2021 Taliban increased coal extraction to fund government operations"}]'::jsonb, '[{"year": null, "event": "All Afghan coal mines: artisanal methods, no safety oversight, frequent fatalities, child labour"}, {"year": null, "event": "Samangan province: conflict between Taliban and NRF — mines potentially in disputed territory"}]'::jsonb, NULL, 'Sub-bituminous to bituminous', 'Jurassic coal-bearing sedimentary basin; Dara-i-Suf coalfield; central Afghanistan Jurassic coal province', NULL, NULL, NULL, NULL, NULL, 0, NULL, 'Artisanal room-and-pillar; hand tools; primitive haulage (donkey/manual)', NULL, NULL, NULL, NULL, NULL, 'Hairatan', '["Road truck transport to Mazar-i-Sharif and border crossings"]'::jsonb, NULL, false, '[]'::jsonb)
