INSERT INTO public.coal_mines (mine_name, operator, license_number, contact_email, contact_phone, country, region, address, latitude, longitude, nearest_port, nearest_railway, founded_year, years_in_operation, original_owner, ownership_changes, major_milestones, notable_incidents, estimated_mine_life_remaining_years, coal_type, grade, calorific_value_kcal_kg, moisture_percent, ash_percent, sulfur_percent, size_mm, annual_capacity_tonnes, available_stock_tonnes, mining_method, price_per_tonne_usd, price_basis, minimum_order_tonnes, payment_terms, contract_types, loading_port, transport_modes, lead_time_days, export_license, certifications)
VALUES ('Barapukuria Coal Mine (Barapukuria Coalfield)', 'Barapukuria Coal Mining Company Limited (BCMCL)', 'State concession (Petrobangla/EMRD); mine development agreement with CMC/Xuzhou', NULL, NULL, 'Bangladesh', 'Rangpur Division', 'Barapukuria area, Parbatipur, Dinajpur, Bangladesh; ~319 km north of Dhaka', 25.4963, 88.9533, 'Chittagong Port (~600 km south by road/rail)', 'Parbatipur railway junction — on national rail network', 1998, 20, 'Petrobangla (Government of Bangladesh)', '[{"year": 1985, "event": "Discovery by Geological Survey of Bangladesh (GSB)"}, {"year": 1998, "event": "BCMCL incorporated under Petrobangla"}, {"year": 2005, "event": "Mine commissioned September 2005 — first commercial coal production in Bangladesh"}, {"year": 2006, "event": "Barapukuria Power Station Units 1 and 2 (2x125 MW) commenced commercial operation"}, {"year": 2009, "event": "Production halted Feb 2009 — land subsidence destroyed 300+ acres; resumed March 2009 after compensation"}, {"year": 2018, "event": "Unit 3 (275 MW) commissioned — total 525 MW; coal theft scandal: 145,000 tonnes missing; 19 officials charged"}, {"year": 2023, "event": "December: mine production suspended; resumed February 2024"}, {"year": 2024, "event": "Storage crisis: producing ~5,000 t/day while power plant consumes ~2,400 t/day — 250,000 tonne stockpile overflow"}]'::jsonb, '[{"year": null, "event": "Bangladesh only operating coal mine — sole domestic coal producer as of 2025"}, {"year": null, "event": "525 MW Barapukuria Power Station — Bangladesh first coal-fired power plant"}, {"year": null, "event": "Land subsidence crisis: 627+ acres subsided; 15 villages water access impacted"}, {"year": null, "event": "~390 Mt total deposit; 114.32 Mt proved (EMRD 2021)"}, {"year": null, "event": "BCMCL restricted from open market sales since 2018 — can only sell to PDB"}]'::jsonb, '[{"year": 2005, "event": "Gas leakage accident — required sealing off portion of mine"}, {"year": 2009, "event": "Death of British consultant Albert Banes Davis (gas inhalation)"}, {"year": 2010, "event": "Roof cave-in — 1 killed, 19 wounded"}, {"year": 2012, "event": "Violent clash — 20+ injured over land subsidence compensation"}, {"year": 2018, "event": "145,000 tonnes coal theft — major corruption scandal"}, {"year": 2025, "event": "Feb: Units 1 and 3 shut down (technical failures); resumed after 5 days"}]'::jsonb, NULL, 'Sub-bituminous to high-volatile bituminous', 'Permian Gondwana; Dinajpur coalfield; Seam VI 19.4 m, Seam V 14.9 m; depth 130–180 m production zone', NULL, NULL, NULL, NULL, NULL, 1000000, NULL, 'Underground; designed longwall but uses modified room-and-pillar; continuous miners; significant dewatering', NULL, NULL, NULL, NULL, NULL, 'Chittagong', '["Conveyor and truck to adjacent Barapukuria Power Station (~1.15 km)", "Parbatipur railway"]'::jsonb, NULL, false, '[]'::jsonb)
