INSERT INTO public.coal_mines (mine_name, operator, license_number, contact_email, contact_phone, country, region, address, latitude, longitude, nearest_port, nearest_railway, founded_year, years_in_operation, original_owner, ownership_changes, major_milestones, notable_incidents, estimated_mine_life_remaining_years, coal_type, grade, calorific_value_kcal_kg, moisture_percent, ash_percent, sulfur_percent, size_mm, annual_capacity_tonnes, available_stock_tonnes, mining_method, price_per_tonne_usd, price_basis, minimum_order_tonnes, payment_terms, contract_types, loading_port, transport_modes, lead_time_days, export_license, certifications)
VALUES ('Phulbari Coal Project (Phulbari Coalfield)', 'GCM Resources plc (AIM: GCM) — development licence holder; PowerChina EPC contract March 2024', 'Mining Lease (30-year from 2004; renewable); Scheme of Development submitted Oct 2005 — still awaiting approval', NULL, NULL, 'Bangladesh', 'Rangpur Division', 'Phulbari area, Dinajpur District, northwest Bangladesh; ~350 km from Dhaka; ~10 km from Indian border', 25.19, 88.62, 'Chittagong Port (~640 km southeast); proposed export via Akram Point offshore reloading', 'Phulbari rail connection proposed; Dinajpur/Parbatipur rail nearby', 1998, NULL, 'BHP Minerals (discovered 1994); Asia Energy (acquired 1998)', '[{"year": 1994, "event": "BHP Minerals discovers Phulbari coalfield"}, {"year": 1998, "event": "BHP sells rights; Asia Energy acquires"}, {"year": 2003, "event": "GCM Resources plc incorporated London; AIM listed 2004"}, {"year": 2004, "event": "30-year mining lease granted"}, {"year": 2005, "event": "GCM submits Feasibility Study and Scheme of Development — still unapproved as of 2025"}, {"year": 2006, "event": "30 Aug: Phulbari Massacre — 3 killed, 300+ injured by paramilitary; government banned protests"}, {"year": 2024, "event": "March: GCM signs EPC Contract with PowerChina (~US$1 billion mine infrastructure) — subject to Scheme approval"}, {"year": 2025, "event": "December: MoU with PowerChina extended to December 2027"}]'::jsonb, '[{"year": null, "event": "572 Mt JORC-compliant coal resource — Bangladesh largest coalfield by quality"}, {"year": null, "event": "Phulbari Massacre 30 Aug 2006 — defining event in Bangladesh anti-coal movement"}, {"year": null, "event": "US$1 billion EPC contract with PowerChina (March 2024) — conditional on government approval"}, {"year": null, "event": "20+ years development without commencement"}, {"year": null, "event": "Proposed: three 2,000 MW PowerChina power stations (6,000 MW total)"}]'::jsonb, '[{"year": 2006, "event": "Phulbari Massacre — 3 protesters killed, 300+ injured by Border Guard paramilitary"}, {"year": null, "event": "Phulbari Solidarity Group continuously protests since 2006"}, {"year": null, "event": "WikiLeaks revealed US Embassy pressured Bangladesh to reopen mine"}, {"year": null, "event": "120,000+ people estimated to face displacement; 40,000 direct (BankTrack)"}, {"year": null, "event": "2024 Bangladesh political revolution adds uncertainty to government approval"}]'::jsonb, NULL, 'Thermal (high quality) and semi-soft coking', 'Permian Gondwana; Phulbari coalfield; coal at 130–260 m depth; 5,193 ha mine footprint', NULL, NULL, NULL, NULL, NULL, 0, NULL, 'Proposed open-pit; full dewatering of aquifer required', NULL, NULL, NULL, NULL, NULL, 'Chittagong (proposed)', '["Proposed: rail to Indian border", "River barge and offshore reloading at Akram Point"]'::jsonb, NULL, false, '[]'::jsonb)
