VALUES ('Dighipara Coal Project (Dighipara Coalfield)', 'No operator — development halted. Lease: BCMCL (Petrobangla); feasibility by MIBRAG/FUGRO/RPM consortium 2020', 'Lease awarded to BCMCL 2015 by Government of Bangladesh', NULL, NULL, 'Bangladesh', 'Rangpur Division', 'Dighipara area, Birampur Upazila, Dinajpur District; part of Dinajpur coal belt', 25.50, 88.85, 'Chittagong Port (~600 km southeast)', 'Parbatipur railway junction (close to Dinajpur coal belt)', NULL, NULL, 'Geological Survey of Bangladesh (discovered 1995)', '[{"year": 1995, "event": "Geological Survey of Bangladesh discovers Dighipara coalfield"}, {"year": 2015, "event": "Government leases Dighipara deposit to BCMCL for development"}, {"year": 2017, "event": "Government announces 500 MW power plant proposal; BCMCL commissions feasibility study"}, {"year": 2020, "event": "March: MIBRAG/FUGRO/RPM feasibility study — 706 Mt high-quality coal; investment US$2.79 billion"}, {"year": 2020, "event": "March: Government plans JV between BCMCL and BPDB to develop mine"}, {"year": 2022, "event": "GEM Wiki: project appeared shelved or abandoned; no further updates"}]'::jsonb, '[{"year": null, "event": "706 Mt high-quality coal confirmed by international feasibility (2020) — Bangladesh third-largest coalfield"}, {"year": null, "event": "Proposed 500 MW power plant — never commissioned"}, {"year": null, "event": "US$2.79 billion investment requirement"}, {"year": null, "event": "Shelved — GEM categorises as abandoned/shelved as of 2022"}]'::jsonb, '[{"year": null, "event": "Same dewatering challenge as Phulbari — thick aquifer overburden"}, {"year": null, "event": "Potential displacement of farming communities — same political risks as Phulbari"}]'::jsonb, NULL, 'High quality (high energy, low ash)', 'Permian Gondwana; Dighipara coalfield; coal at ~250 m depth; 24 km2 extent', NULL, NULL, NULL, NULL, NULL, 0, NULL, 'Proposed open-cut; full aquifer dewatering required', NULL, NULL, NULL, NULL, NULL, 'Chittagong (proposed)', '["Proposed: rail/road to power station on-site"]'::jsonb, NULL, false, '[]'::jsonb)
