VALUES ('Bhutan — Khotokha Coalfield Area (Tshophangma and Habrang Coal Mines — SMCL)', 'State Mining Corporation Limited (SMCL) — 100% Government of Bhutan', 'Mine leases held by SMCL; Tshophangma — 105.62 acres leasehold (Phuntshothang Gewog)', NULL, NULL, 'Bhutan', 'Samdrup Jongkhar Dzongkhag', 'Northeast of Khatoethang village, Phuntshothang Gewog, Samdrup Jongkhar District, southeastern Bhutan', 26.95, 91.50, 'Kolkata/Haldia, India (~800 km south via road and Indian rail)', 'Indian railway at border; Assam/West Bengal rail via Samdrup Jongkhar', 2015, 10, 'SMCL (State Mining Corporation Limited)', '[{"year": 2014, "event": "SMCL incorporated (31 December 2014); assumes government coal mining mandates"}, {"year": 2015, "event": "SMCL commences operations — Tshophangma and Habrang mines; later adds Reshore and Majuwa"}, {"year": 2021, "event": "RAA performance audit: SMCL missed coal production targets"}, {"year": 2021, "event": "SMCL floated tenders for Tshophangma and Habrang after PDKPL disqualified"}]'::jsonb, '[{"year": null, "event": "SMCL total assets grew from Nu. 0.36 billion (2017) to Nu. 3.22 billion (2022)"}, {"year": null, "event": "SMCL coal mines target: 0.66 million MT by end-2022 (Tshophangma, Habrang, Reshore, Majuwa)"}, {"year": null, "event": "Bhutan total coal production 2019: ~187,000 MT"}, {"year": null, "event": "Coal exports to India (cement industry); 72.5%+ of Bhutan mineral exports are industrial minerals including coal"}, {"year": null, "event": "Bhutan electricity is 100% hydropower — coal has no role in power generation"}]'::jsonb, '[{"year": null, "event": "PDKPL (community cooperative) invested Nu. 4.187 million for Tshophangma machinery; disqualified from contract 2021; investment lost — governance failure (RAA 2024)"}]'::jsonb, NULL, 'Sub-bituminous to bituminous', 'Permian Gondwana Khotokha Formation; Ecca Group / Karoo-equivalent; southeastern Bhutan', NULL, NULL, NULL, NULL, NULL, 187000, NULL, 'Open cast surface mining; contractor-operated under SMCL management', NULL, NULL, NULL, NULL, NULL, 'Kolkata/Haldia', '["Road truck to cement plants within Bhutan", "Road to Indian border for exports"]'::jsonb, NULL, true, '[]'::jsonb)
