INSERT INTO public.coal_mines (mine_name, operator, license_number, contact_email, contact_phone, country, region, address, latitude, longitude, nearest_port, nearest_railway, founded_year, years_in_operation, original_owner, ownership_changes, major_milestones, notable_incidents, estimated_mine_life_remaining_years, coal_type, grade, calorific_value_kcal_kg, moisture_percent, ash_percent, sulfur_percent, size_mm, annual_capacity_tonnes, available_stock_tonnes, mining_method, price_per_tonne_usd, price_basis, minimum_order_tonnes, payment_terms, contract_types, loading_port, transport_modes, lead_time_days, export_license, certifications)
VALUES ('Cambodia — Kampot Region (No Historical Coal Mine; Coal Activity in Oddar Meanchey Province)', 'None at Kampot (Kampot is limestone/cement province). Active coal: Han Seng Coal Mine (Oddar Meanchey — operating Jan 2021)', 'One exploration coal licence noted historically (MIME 1994–2006 — location not confirmed as Kampot)', NULL, NULL, 'Cambodia', 'Kampot Province (no coal); Oddar Meanchey Province (active coal)', 'Kampot Province, coastal southwest Cambodia; Active coal: Oddar Meanchey Province, northern Cambodia near Thai border', 10.61, 104.18, 'Sihanoukville (Preah Sihanouk) — Cambodia main deep-water port (~20 km from Kampot)', 'Royal Railway Cambodia — Phnom Penh to Sihanoukville/Kampot line', NULL, NULL, NULL, '[{"year": 2006, "event": "MIME granted 1 coal exploration licence (1994–2006) — location unspecified"}, {"year": 2021, "event": "Han Seng Coal Mine (Oddar Meanchey) commences Phase 1 — first domestic coal in Cambodia"}, {"year": 2021, "event": "Cambodia COP26 pledge: no additional coal projects approved after 2021"}, {"year": 2023, "event": "Oddar Meanchey Han Seng power plant (265 MW) still under construction; stalled by Chinese contractor issues"}]'::jsonb, '[{"year": null, "event": "Kampot Province: NO coal mining history — cement/limestone is its mineral identity"}, {"year": null, "event": "Cambodia active coal: Han Seng Coal Mine (Oddar Meanchey) — 1 Mtpa nameplate; operational Jan 2021"}, {"year": null, "event": "JDI 2009 study: two northern Cambodia coal sites — 34 Mt and 120 Mt"}, {"year": null, "event": "Cambodia imports all thermal coal for power (Preah Sihanouk plants burn Indonesian coal)"}, {"year": null, "event": "Cambodia pledged no new coal approvals post-2021 but three existing projects exempted"}]'::jsonb, '[{"year": null, "event": "Han Seng power plant missed 2022 completion; construction dormant 1+ year; pivoted to partial solar"}, {"year": null, "event": "Royal Group (Koh Kong) coal plant — land in Botum Sakor National Park; evictions alleged; project dormant 2023"}, {"year": null, "event": "Oddar Meanchey residents: we are afraid to protest — community powerlessness documented"}]'::jsonb, NULL, 'N/A for Kampot. Oddar Meanchey: sub-bituminous/lignite', 'Kampot: marine limestone (Mesozoic) — NO coal. Cambodia coal: Jurassic/Cretaceous lignite in Oddar Meanchey, Siem Reap', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, '[]'::jsonb)
